<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\Accessor\TenantMarkForDeleteAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantMarkForDeleteAccessor trait.
 *
 * Covers null default, string/VO assignment via withMarkForDelete,
 * getMarkForDelete/markForDelete accessors, and isMarkForDeleteChanged with/without original.
 */
class TenantMarkForDeleteAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withMarkForDelete creates a new instance with the MarkForDelete set
     * from a string value, and getMarkForDelete returns the primitive string.
     */
    public function testWithMarkForDeleteFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantMarkForDeleteAccessorUnitTest();

        // Act
        $result = $holder->withMarkForDelete(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isMarkForDelete());
    }
    /**
     * Asserts that withmarkForDelete has access to the value object
     * from a string value, and getMarkForDelete returns the primitive string.
     */
    public function testWithMarkForDeleteFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantMarkForDeleteAccessorUnitTest();

        // Act
        $result = $holder->withMarkForDelete(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->markForDelete()->value());
    }
    public function testChangedMarkForDelete(): void
    {
        // Arrange
        $holder = new ImplWithTenantMarkForDeleteAccessorUnitTest()->withMarkForDelete(true);
        $original = $holder->withMarkForDelete(true);
        $same = $holder->withMarkForDelete(true);
        $modified = $holder->withMarkForDelete(false);

        // Act
        $withSame = $original->isMarkForDeleteChanged($same);
        $withDiferent = $original->isMarkForDeleteChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantMarkForDeleteAccessorUnitTest
{
    use TenantMarkForDeleteAccessor;
}
